xmlDictQLookup(xmlDictPtr dict, const xmlChar *prefix, const xmlChar *name) {
    xmlDictEntry *entry;
    unsigned int len, l, i;
    xmlChar c;
    unsigned int hashValue;
    int ret;

    if ((dict == NULL) || (name == NULL))
